(286, 'مفوض', 5, 'فيلا', 'إيجار', 'فيلا للايجار حي سدرة روشن', 'فيلا للإيجار في حي سدرة – روشن | الرياض\n\nفرصتك للسكن في أحد أرقى أحياء شمال الرياض\n\nفيلا عصرية بمساحة 250 م² في حي “سدرة” من روشن – مصممة بعناية لتناسب احتياجات العائلة العصرية.\n\n⸻\n\n✅ مواصفات الفيلا:\n	•	المساحة: 250 م²\n	•	عدد الغرف: 3 غرف نوم \n	•	دورات المياه: 3\n	•	صالتين واسعة بالدور الأرضي و الأول\n	•	مطبخ مفتوح بأناقة عصرية\n	•	حديقة خارجية صغيرة / حوش خاص\n- غرفة خادمة\n	•	موقف سيارات\n	•	تشطيبات راقية\n- تكييف VRF\n\n⸻\n\n مميزات السكن في حي سدرة – روشن:\n\n✔️ حي متكامل الخدمات والبنية التحتية\n✔️ حدائق، ملاعب أطفال، مسارات للمشي\n✔️ مساجد، محلات، ومراكز مجتمعية\n✔️ أمن 24/7\n✔️ موقع استراتيجي بالقرب من:\n	•	مطار الملك خالد\n	•	واجهة الرياض\n	•	جامعة الأميرة نورة\n\n⸻', 'منطقة الرياض   مدينة  الرياض  حي  سدرة رقم 1205', '[{\"name\":\"حمام\", \"number\":\"3\"},{\"name\":\"غرف نوم\", \"number\":\"3\"},{\"name\":\"صالات\", \"number\":\"2\"},{\"name\":\"مطبخ\", \"number\":\"1\"}]', '250', '100000', '[]', 9061, 'active', 'سدرة', '[]', '[]', NULL, '[\"1755937157_image_picker_AE855A6A-4A1F-4308-9A29-21D4B86B84A7-55696-00000513B25D5594.jpg\"]', NULL, '24.861955987078467', '46.742696711901985', 'الرياض', '[]', 1, 205, 1, 'سنتين', '[]', NULL, 'منطقة ال', NULL, 234324, '7100204894', NULL, '2025-08-23 05:18:20', '2026-05-01 02:57:47', '[]', NULL, '12', NULL, 'فيلا', '399005000126', 'video_1755947636.mov', NULL, NULL, '1', '1100252397', '7100204894', '23/08/2025', '19/08/2026', '399005000126', '7100204894', '1100252397', 'صك إلكتروني', '7100204894', NULL, NULL, NULL, NULL, NULL, 'شمالية', NULL, 13421, '3967 / 14', 'لا يوجد', '', 'حي سدرة في  مدينة الرياض', '3', NULL, '564', '[\"\\u0643\\u0647\\u0631\\u0628\\u0627\\u0621\",\"\\u0645\\u064a\\u0627\\u0647\",\"\\u0635\\u0631\\u0641 \\u0635\\u062d\\u064a\"]', 'سكني', 'https://eservicesredp.rega.gov.sa/public/queries/IndividualBroker/ElanDetails/08dde21c-785a-4f59-8a3e-cd16c5a17f00', 'أمل مسفر بن عايض القحطاني', '0575057070', 1, '1097244691'),
