(300, 'مفوض', 41, 'معرض', 'بيع', 'محل تجاري للبيع بجدة حي السلامة', 'تملك الآن لاستثمار مستقبلي بعائد مجزئ \nمحلات تجارية للبيع في مدينة جدة حي السلامة \nمحلات قيد الإنشاء على شارعين\nمكونة من أربع محلات تجارية دور وميزانين \nنافذ على ممشى اليمامة وبجوار حديقة \nواجهة مودرن ، تأسيس مكيفات سبيلت ، د خول ذكي \nعداد مستقل و خزان مستقل \nعبارة عن أربع محلات تجارية تختلف مساحاتها \nمساحات مختلفة تبدأ من  40 م  إلى 53 م \nعلى شارعين وعلى شارع واحد\n▪️عرض الشارع /20 \nشارع 20م / 12م الجانبي\nواجهة : شمالية غربية \nمعرض دور أرضي فقط + ميزانين \nمتوفرضمانات على المبنى \n25 سنة على الهيكل الإنشائي \n25سنة قواطع وأفياش \n3سنوات السباكة والكهرباء \nالمطلوب \nتبدأ من 720 ألف ريال إلى 750 ألف ريال  \n\nترخيص إعلاني  \n7100206850', 'منطقة مكة المكرمة   مدينة  جدة  حي  السلامة مواكب النصر', '[{\"name\":\"حمام\", \"number\":\"1\"},{\"name\":\"غرف نوم\", \"number\":\"0\"},{\"name\":\"صالات\", \"number\":\"0\"},{\"name\":\"مطبخ\", \"number\":\"0\"}]', '720', '750000', '[]', 2031, 'active', 'السلامة', '[]', '[]', NULL, '[\"1756471197_image_picker_88F1A30F-53C3-421F-A19D-F4CA186DC85D-38266-000015774064E4AD.png\",\"1756471197_image_picker_C0528045-4EB2-4817-8BB9-D3267EAAF42C-38266-0000157740438938.png\",\"1756471197_image_picker_5ED549C3-2D42-432F-98D9-C2A20A66AF9E-38266-00001577408208B2.png\",\"1756471197_image_picker_17F6EC1F-D4B2-45E8-9385-37FA8B1E656E-38266-0000157740D6E93F.png\",\"1756471197_image_picker_475124B3-1EFC-4E62-ACF0-E1E128D4D403-38266-00001577409E2E53.png\",\"1756471197_image_picker_881F3A6E-569C-4921-8833-7CE666ABD174-38266-0000157740BBE0B6.png\",\"1756471197_image_picker_488B42B3-706A-4D2C-85FC-09414C8F1CF9-38266-00001577402F1F7C.png\"]', NULL, '21.586215085189785', '39.15717858220162', 'جدة', '[{\"name\": \"توفر هاتف ارضي\"}, {\"name\": \"توفر كهرباء\"}, {\"name\": \"توفر ماء\"}, {\"name\": \"مدخل سيارة\"}, {\"name\": \"مصعد\"}, {\"name\": \"الدخول الذكي\"}]', 2, 227, 1, 'جديد', '[]', NULL, 'منطقة مك', NULL, 234324, '7100206850', NULL, '2025-08-29 09:39:18', '2026-05-