(412, 'مفوض', 30, 'دور', 'إيجار', 'دور للايجار بحي العقيق', 'للايجار \nحي العقيق\nدور علوي خمس غرف\nمدخلين .. مجدد كلياً\n\nموقع مميز\nقريب من جميع الخدمات\n5 دقايق للبولفارد\n10 دقايق الى محطة كافد\n\nيتكون من :-\nمجلس . مقلط\n3 غرف نوم وحده ماستر\n\nمطبخ (غير راكب)\n+ صالة\n+ 3دوارت مياه\n\nمكيفات اسبلت راكب', 'منطقة الرياض   مدينة  الرياض  حي  العقيق رابح', '[{\"name\":\"حمام\", \"number\":\"3\"},{\"name\":\"غرف نوم\", \"number\":\"5\"},{\"name\":\"صالات\", \"number\":\"1\"},{\"name\":\"مطبخ\", \"number\":\"1\"}]', '450', '85000', '[]', 2372, 'active', 'العقيق', '[]', '[]', NULL, '[\"1759016145_image_picker_DA766676-C463-4B8C-A2E7-D9262DE63198-27849-00000AF85B03FCBE.jpg\"]', NULL, '24.787904541254765', '46.618649825015986', 'الرياض', '[]', 1, 205, 1, 'اكثر من عشر سنوات', '[]', NULL, 'منطقة ال', NULL, 234324, '7100218476', NULL, '2025-09-27 20:35:30', '2026-05-01 02:55:48', '[]', NULL, '0', NULL, 'دور', '414010001503', NULL, NULL, NULL, '1', '1100252397', '7100218476', '28/09/2025', '26/09/2026', '414010001503', '7100218476', '1100252397', 'صك إلكتروني', '7100218476', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 13515, '1863 / أب', 'لا يوجد', '', 'حي العقيق في  مدينة الرياض', '5', NULL, '1150 / 1', '[\"\\u0643\\u0647\\u0631\\u0628\\u0627\\u0621\",\"\\u0645\\u064a\\u0627\\u0647\",\"\\u0635\\u0631\\u0641 \\u0635\\u062d\\u064a\"]', 'سكني', 'https://eservicesredp.rega.gov.sa/public/IndividualBroker/ElanDetails/08ddfe1d-0886-40ff-817c-f144b62d6a21', 'أمل مسفر بن عايض القحطاني', '0575057070', 1, '1097244691'),
(413, 'مفوض', 32, 'شقة', 'إيجار', 'شقة للايجار حي الرمال', '🌟 للإيجار – دور علوي كامل مستقل مع سطح 🌟\n📍 الموقع: الرياض – حي الرمال (تنال) 🏙️  \n✅ موقع استراتيجي وقريب من مطار الملك خالد الدولي \n\n🏡 تفاصيل الدور:\n🔹 جديد بالكامل ولم يؤجر من قبل\n🔹 مدخل مستقل لخصوصية تامة 🚪\n🔹 المجلس مؤثث بالكامل (كنب + ديكورات راقية) 🛋️\n🔹 مجلس كبير جداً مع واجهة زجاجيه مطلة على السطح ✨🌿 (ويوجد مساحة كبيره لوضع جلسات خارجية مثالية)\n🔹 صالة عائلية مريحة 👨‍👩‍👧‍👦\n🔹 غرفة ماستر واسعة مؤثثه بالكامل + غرفتين نوم غير مؤثثه 🛏️ \n🔹 مقلط 🍽️\n🔹 مطبخ + منطقة غسيل 🍳🧺\n🔹 3 دورات مياه 🚿🚽\n🔹 مكيفات سبليت راكبة ❄️', 'منطقة الرياض   مدينة  الرياض  حي  الرمال 0', '[{\"name\":\"حمام\", \"number\":\"3\"},{\"name\":\"غرف نوم\", \"number\":\"3\"},{\"name\":\"صالات\", \"number\":\"1\"},{\"name\":\"مطبخ\", \"number\":\"1\"}]', '327.4', '50000', '[]', 5680, 'active', 'الرمال', '[]', '[]', NULL, '[\"1759130490_image_picker_6134DC58-2E08-47CB-9F32-C97F780F353C-46688-00000C955BFDC535.jpg\",\"1759130490_image_picker_5E817BDD-BE12-423F-9D0A-3CA6FB29A340-46688-00000C955BE7D315.jpg\",\"1759130490_image_picker_2F601472-046D-429A-A9B3-DE258F8DFF07-46688-00000C955C415A45.jpg\",\"1759130490_image_picker_FD62D11E-3F4A-4311-8B72-38B9E412091C-46688-00000C955C21298D.jpg\",\"1759130490_image_picker_BF23BE54-401E-4E85-B3D4-5141D1B5AD01-46688-00000C955C4E803F.jpg\",\"1759130490_image_picker_7E72DE47-1BE9-40BE-8C5E-A7AA115AC2ED-46688-00000C955C58F580.jpg\",\"1759130490_image_picker_F992745E-2431-433F-A6B6-70A62F2B6D87-46688-00000C955C078610.jpg\",\"1759130490_image_picker_9E3C1415-5CA4-4950-BA19-DD0535A27DE6-46688-00000C955C2E47E8.jpg\",\"1759130490_image_picker_52022510-83A5-434A-82B3-4B51CCE72E38-46688-00000C955C14C889.jpg\"]', NULL, '24.922367041030338', '46.793441565469685', 'الرياض', '[]', 1, 205, 1, 'ثلاث سنوات', '[]', NULL, 'منطقة ال', NULL, 234324, '7100218964', NULL, '2025-09-29 04:20:52', '2026-05-01 02:55:50', '[]', NULL, '0', NULL, 'شقة', '794535003500', NULL, NULL, NULL, '1', '1100252397', '7100218964', '29/09/202