(479, 'مفوض', 5, 'فيلا', 'إيجار', 'تاون هاوس (شقة دورين) للإيجار بالنرجس', '🏠 للإيجار تاون هاوس فاخر (شقة دورين جديدة) في موقع مميز حي النرجس من مشروع رافال الجزيرة للتطوير والاستثمار العقاري \n\n🔰المساحة ١٧٦م\n\nمميزات الوحدة: \n✅ تشطيبات فاخرة رخامية \n✅دخول ذكي \n✅مصممة وفق كود البناء الجديد \n✅نظام كامل للحماية من الحرائق\n\nتفاصيل الوحدة:\n* الدور الأرضي\n📺 1 صالة\n🛋️ 1 مجلس \n🛁 1 دورة مياة ومغسلة رخامية\n🚪مدخل خاص\n🛻 موقف خاص \n🏘️ حوش/ارتداد خارجي \n\n* الدور الاول\n\n📺 1 صالة\n🛏️ 2 غرفتين ماستر \n🛁 2 دورة مياة \n🪦 منور\n\n📍مميزات الموقع:\n3 دقائق عن طريق الملك سلمان \n4 دقائق من طريق أبو بكر\n15 دقيقة من مطار الملك خالد \n15 دقيقة من جامعة الامام \n12 دقيقة من جامعة الأميرة نورة \n\n💵 السعر ٩٠ ألف\n\nمع وجود كافة الضمانات الإنشائية والهندسية والمعمارية والصحية', 'منطقة الرياض   مدينة  الرياض  حي  النرجس علقمة بن وائل', '[{\"name\":\"حمام\", \"number\":\"2\"},{\"name\":\"غرف نوم\", \"number\":\"2\"},{\"name\":\"صالات\", \"number\":\"1\"},{\"name\":\"مطبخ\", \"number\":\"1\"}]', '144.21', '90000', '[]', 3473, 'active', 'النرجس', '[]', '[]', NULL, '[\"1760519114_image_picker_90CF3357-198C-4408-A412-650C8C08CE3E-12014-000009D2FE56EF95.jpg\",\"1760519114_image_picker_6A7082B8-0715-4EA3-9571-99377382F96C-12014-000009D2FE67776F.jpg\",\"1760519114_image_picker_7C5AFF6D-D40F-4DB1-A376-74435A86B9A5-12014-000009D2FE35BE3C.jpg\",\"1760519114_image_picker_88D8F83F-5BEA-4FDE-8425-F81D31036994-12014-000009D2FE5C3811.jpg\",\"1760519114_image_picker_F5DCE4D9-DE1F-4B54-9EE1-705284E25420-12014-000009D2FE7A843A.jpg\",\"1760519114_image_picker_AE2329EC-24A8-442B-A67B-3B0E9490C6C9-12014-000009D2FE5057A8.jpg\",\"1760519114_image_picker_BB8DBB7C-62B4-45EE-86F0-A6949DE2E887-12014-000009D2FE614692.jpg\",\"1760519114_image_picker_94398BE2-2837-4F1D-A632-ED0E67F6C546-12014-000009D2FE2B6310.jpg\"]', NULL, '24.8561853857358', '46.657690662868326', 'الرياض', '[]', 1, 205, 1, 'جديد', '[]', NULL, 'منطقة ال', NULL, 234324, '7100224684', NULL, '2025-10-15 06:04:28', '2026-05-01 02:54:34', '[]'