(483, 'مفوض', 5, 'فيلا', 'بيع', 'فيلا عصرية بتصميم فاخر 🏠', 'فيلا أنيقة تجمع بين الفخامة والراحة، بتصميم حديث\nتشطيبات عالية الجودة وموقع هادئ يوفر خصوصية تام\n✨السعر شامل السعي ✨\n4 غرف نوم \n5 دورات مياه \nصالة\nمطبخ\nمجلس خارجي مستقل\nغرفة غسيل \nأفنية خارجية\nإطلالات زجاجية\nضمانات الهيكل الإنشائي ✨\nضمانات السباكة والكهرباء ✨', 'منطقة الرياض   مدينة  الرياض  حي  الفاروق يحيى بن اسماعيل', '[{\"name\":\"حمام\", \"number\":\"5\"},{\"name\":\"غرف نوم\", \"number\":\"4\"},{\"name\":\"صالات\", \"number\":\"1\"},{\"name\":\"مطبخ\", \"number\":\"1\"}]', '260', '2150000', '[]', 3068, 'active', 'الفاروق', '[]', '[]', NULL, '[\"1760621040_image_picker_D4FE0E0F-AD83-4317-8E53-C486903CE32F-4053-0000022728849FDD.jpg\",\"1760621040_image_picker_4032383A-C839-4206-B923-DEB8417D1FDB-4053-0000022728CCB7E1.jpg\",\"1760621040_image_picker_FE10F857-9EAA-48F3-B257-79BED7A7DF2A-4053-000002272917EF8F.jpg\",\"1760621040_image_picker_F0C0B0E9-FFCB-4D4D-996A-A29AC5F947EB-4053-0000022728BA9FEB.jpg\",\"1760621040_image_picker_CCB9B868-E748-4F45-B33B-51808E756ACF-4053-000002272905153A.jpg\",\"1760621040_image_picker_C2842EC4-5020-4F27-A94C-B922306A7E99-4053-0000022729295019.jpg\",\"1760621040_image_picker_8A9A794D-FFC1-42AB-ACFF-F918D5522DD0-4053-0000022728977441.jpg\",\"1760621040_image_picker_2037353D-8AD8-4504-9A1F-33520DCC4CC2-4053-0000022728A87A22.jpg\",\"1760621040_image_picker_5EA07FFD-FA16-4197-9E0E-04E050782CD3-4053-0000022728E12C73.jpg\",\"1760621040_image_picker_48B370BB-63B6-4AAB-A25F-47027A6F7477-4053-0000022728F1D318.jpg\"]', 'https://drive.google.com/file/d/1PKgL1zYatOyq6Z_vnUjjMBowpV-0Eau9/view?usp=drivesdk', '24.656646896821957', '46.7865782314288', 'الرياض', '[{\"name\": \"توفر كهرباء\"}, {\"name\": \"توفر ماء\"}, {\"name\": \"مدخل سيارة\"}, {\"name\": \"درج صالة\"}]', 1, 352, 1, 'جديد', '[]', NULL, 'منطقة ال', NULL, 234324, '7100223471', NULL, '2025-10-16 10:14:11', '2026-05-01 02:54:23', '[]', NULL, '25', NULL, 'فيلا', '6085321816900000', 'video_1760621154.mp4', NULL, NU