(486, 'مفوض', 32, 'شقة', 'بيع', 'شقة للبيع بمدينة جدة حي الحرمين المروة', 'شقة مستخدمة للبيع في موقع مميز في مخطط حي الحرمين - 1\nمساحةالشقه : 208 م \nمكونة الشقة من \n1غرفة ماستر بدورة مياه \n3غرف نوم \nصالون ضيوف وصالة  طعام \n2 صالتان مفتوحتان على بعض \nمطبخ جاهز \n٤ دورات مياه \nغرفة عاملة \nالدور الأول \nمصعد \nمميزات الشقة \nيتميز بوجود\nمدخلين للشقة\nشقة واسعة وكبيرة\nمطبخ مفتوح وجاهز\nالعمارة أمام مسجد و حديقة\nغرفة عاملة بدورة مياه خاصة \nغرفة سائق وموقف خاص \nمساحةالشقه : 208 م \nخزان مستقل \nوعداد كهرباء مستقل \nعمر الشقة أكثر من 10 سنوات\nالمطلوب \n750 ألف ريال', 'منطقة مكة المكرمة   مدينة  جدة  حي  المروة أنيس بن نواس', '[{\"name\":\"حمام\", \"number\":\"4\"},{\"name\":\"غرف نوم\", \"number\":\"6\"},{\"name\":\"صالات\", \"number\":\"2\"},{\"name\":\"مطبخ\", \"number\":\"1\"}]', '208.43', '750000', '[]', 5128, 'active', 'المروة', '[]', '[]', NULL, '[\"1760738532_image_picker_78076A93-F21A-46D2-AC60-8C7DD5EBE2E2-40424-00000FCBA7CFAE30.png\",\"1760738532_image_picker_D5149FBD-8628-4F06-ACBC-14C810AB1777-40424-00000FCBA7A914B3.png\",\"1760738532_image_picker_7C531592-E1B2-4D2F-9B66-D51C6EFF1A01-40424-00000FCBA8709588.png\",\"1760738532_image_picker_C5D77421-81A8-458A-B45A-0135E99C69C7-40424-00000FCBA8498481.png\",\"1760738532_image_picker_AFE6B148-AF50-47E9-82E9-ACCBB9048BDA-40424-00000FCBA7F85683.png\",\"1760738532_image_picker_B2AE042A-787F-4EC0-99B6-D59F92C1FC2B-40424-00000FCBA77F0EA4.png\",\"1760738532_image_picker_D024FABE-BCCF-4123-A377-4CA09D72FD0F-40424-00000FCBA819821D.png\",\"1760738532_image_picker_61D452F7-DC6B-4975-9193-9823B209FBCC-40424-00000FCBA7555E73.png\"]', NULL, '21.608525487428587', '39.21265163320099', 'جدة', '[{\"name\": \"توفر كهرباء\"}, {\"name\": \"توفر ماء\"}, {\"name\": \"مدخل سيارة\"}, {\"name\": \"عرفة خادمة\"}, {\"name\": \"غرفة سائق\"}, {\"name\": \"مصعد\"}]', 2, 227, 1, 'اكثر من عشر سنوات', '[]', NULL, 'منطقة مك', NULL, 234324, '7100225573', NULL, '2025-10-17 19:01:56', '2026-05-01 02:54:25', '[]', NULL, '0', NULL, 'شقة', '