(492, 'مفوض', 32, 'شقة', 'إيجار', 'شقة للإيجار بالدرعية الجديدة', 'الدرعية الجديدة\nشقه ( لعرسان ) في فيلا خاصة \n  2غرفة نوم\n1 صالة\n1 مطبخ ☑️راكب\n1 مجلس\n2 دورة مياه \nخمس نجوم تشطيب ديلوكس فندقي \nالشقة العلوية 50 ألف\nعداد كهرباء مستقل', 'منطقة الرياض   مدينة  الدرعية  حي  ظهرة العودة شرق الجهيمي', '[{\"name\":\"حمام\", \"number\":\"2\"},{\"name\":\"غرف نوم\", \"number\":\"2\"},{\"name\":\"صالات\", \"number\":\"1\"},{\"name\":\"مطبخ\", \"number\":\"1\"}]', '450', '50000', '[]', 8138, 'active', 'ظهرة العودة شرق', '[]', '[]', NULL, '[\"1760903564_image_picker_7E912ECE-A8B1-47BD-A167-21156B27F3C1-14077-000001F77CDDC430.jpg\",\"1760903564_image_picker_A01D1190-6A45-401C-8A69-CB455367A339-14077-000001F77D0FA743.jpg\",\"1760903564_image_picker_DE48A29C-1662-4872-8205-51823615621E-14077-000001F77CD2668A.jpg\",\"1760903564_image_picker_720CDBAE-7B3B-470D-B117-4A5329BC8DD3-14077-000001F77D1D0BE9.jpg\",\"1760903564_image_picker_42049A95-D0B9-438E-9176-5DF4D26A9211-14077-000001F77C9C306F.jpg\",\"1760903564_image_picker_C3418CB6-247A-4F9A-AAF9-BC0E019D240E-14077-000001F77CBA2288.jpg\",\"1760903564_image_picker_9E23DDF6-1443-453F-8EC4-15790CE9D286-14077-000001F77CF8BF52.jpg\",\"1760903564_image_picker_CD1CF523-7765-4997-AD1A-C5F96850E3A8-14077-000001F77CEBD81A.jpg\",\"1760903564_image_picker_E69DF2FA-4267-49A7-8F9F-8F958055808A-14077-000001F77CC5ADA7.jpg\",\"1760903564_image_picker_2AF67F0F-D78F-44BE-8A92-A4E8E13EF01D-14077-000001F77CADFC9C.jpg\",\"1760903564_image_picker_011B94BD-8059-479B-82CE-857686E8E307-14077-000001F77C880AE4.jpg\",\"1760903564_image_picker_5F15967C-CC0A-4AC0-B662-9E6C0E891F5F-14077-000001F77D0571C2.jpg\"]', NULL, '24.750451961289574', '46.52548272148563', 'الدرعية', '[]', 1, 205, 1, 'خمس سنوات', '[]', NULL, 'منطقة ال', NULL, 234324, '7100226185', NULL, '2025-10-19 16:34:04', '2026-05-01 02:54:12', '[]', NULL, '0', NULL, 'شقة', '5359477858900000', 'video_1760903610.mov', NULL, NULL, '1', '1100252397', '7100226185', '19/10/2025', '18/10/2026', '5359477