(505, 'مفوض', 1, 'ارض', 'بيع', 'للبيع ارض سكنيه', '📍 للبيع أرض سكنية زاوية – حي عرقة، الرياض\n\nمن المالك مباشرة – بدون وسطاء أو مكاتب عقارية\n\n📐 المساحة: 850 م²\nالأطوال:\n	•	22.30 م على شارع 12\n	•	عمق 38.31 م\n\n🔹 المواصفات:\n	•	زاوية\n	•	أرض صخرية (ليست دفّان)\n	•	موقع داخلي هادئ – غير مطلة على الوادي\n	•	مناسبة لبناء سكن شخصي أو 3 فلل خاصة\n	•	لا تقبل التقسيم\n\n📍 الموقع: حي عرقة – غرب الرياض\n\n💰 السعر المطلوب: 6,500 ريال للمتر\n\n🚫 يُمنع التواصل من المكاتب العقارية أو الوسطاء\n\n📞 للاستفسار الجاد:\nأبو فيصل', 'منطقة الرياض   مدينة  الرياض  حي  عرقة', '[{\"name\":\"حمام\", \"number\":\"0\"},{\"name\":\"غرف نوم\", \"number\":\"0\"},{\"name\":\"صالات\", \"number\":\"0\"},{\"name\":\"مطبخ\", \"number\":\"0\"}]', '854.7', '6500', '[]', 9347, 'active', 'عرقة', '[]', '[]', NULL, '[\"1761318181_image_picker_95B75B88-2A53-44B7-BDD4-E11384AFAA1D-12814-00000405F7B1D8A9.jpg\",\"1761318181_image_picker_4D9DE997-5C39-4749-8BF0-35FFFF14FED8-12814-00000405F7C57AEB.jpg\"]', NULL, '24.678651560396688', '46.604573775461986', 'الرياض', '[]', 1, 389, 1, NULL, '[]', NULL, 'منطقة ال', NULL, 234324, '7100142026', NULL, '2025-10-24 11:55:07', '2026-05-01 02:54:01', '[]', NULL, '12', NULL, 'ارض', '260690002208', NULL, NULL, NULL, '1', '1100276567', '7100142026', '14/02/2025', '01/12/2025', '260690002208', '7100142026', '1100276567', 'صك إلكتروني', '7100142026', 'قطعة رقم 700 اثنين و عشرون متر و واحد و ثلاثون سنتمتر', 'ممر مشاه عرض 4 م ثمانية و ثلاثون متر و واحد و ثلاثون سنتمتر', 'قطعة رقم 725 ثمانية و ثلاثون متر و واحد و ثلاثون سنتمتر', 'شارع عرض 12 م اثنين و عشرون متر و واحد و ثلاثون سنتمتر', NULL, 'جنوبية', '5555550', NULL, '2811', '0', '', 'حي  عرقة  بمدينة الرياض .', NULL, 'سكني', '724', '[\"\\u0644\\u0627\\u064a\\u0648\\u062c\\u062f \\u062e\\u062f\\u0645\\u0627\\u062a\"]', NULL, 'https://eservicesredp.rega.gov.sa/public/IndividualBroker/ElanDetails/08dd4aee-7b07-4a5d-8439-e4d62e4a3e45', NULL, NULL, 1, '1036966297'),
