(522, 'مفوض', 1, 'ارض', 'بيع', '🏡 للبيع قطعة ارض مميزة في مدينة الخبر', '📍 الموقع: الخبر – حي الأمواج\n📑 رقم المخطط: 711 ش.خ\n🔢 رقم القطعة: 10\n📏 المساحة: 375 م²\n🏷️ نوع العقار: قطعة أرض\n🏙️ الحي: مكتمل الخدمات، قريب من الطرق الرئيسية والمرافق الحيوية\n🚗 الواجهة: شارع 16 متر غربي\n\n\n✨ مميزات الموقع:\n\nموقع مميز في حي الأمواج – مدينة الخبر.\nأرض نظامية موثقة من وزارة العدل.\nمناسبة للاستثمار أو البناء السكني.\nقريبة من الطرق والخدمات الحيوية.\n\n🔖 رقم رخصة فال: 1200029011\n🔖 رقم الترخيص الإعلاني: 7200750433\n📞 للتواصل والاستفسار:\nشركة همم الشرق العقارية\n📱 0546666095\nK:00', 'المنطقة الشرقية   مدينة  الخبر  حي  الأمواج عامر البكير', '[{\"name\":\"حمام\", \"number\":\"0\"},{\"name\":\"غرف نوم\", \"number\":\"0\"},{\"name\":\"صالات\", \"number\":\"0\"},{\"name\":\"مطبخ\", \"number\":\"0\"}]', '375', '1400', '[]', 4509, 'active', 'الأمواج', '[]', '[]', NULL, '[]', NULL, '26.139249227744976', '50.156937748313936', 'الخبر', '[]', 5, 370, 1, NULL, '[]', NULL, 'المنطقة ', NULL, 234324, '7200750433', NULL, '2025-11-05 12:31:46', '2026-04-26 12:43:26', '[]', NULL, '20', NULL, 'ارض', '660026508897', NULL, NULL, NULL, '2', '1200029011', '7200750433', '05/11/2025', '10/02/2026', '660026508897', '7200750433', '1200029011', 'صك إلكتروني', '7200750433', NULL, NULL, NULL, NULL, NULL, 'جنوبية', '525000', 34751, 'ش خ711معدل1', 'لا', '', 'حي الامواج في  مدينة الخبر', NULL, NULL, '10', '[\"\\u0643\\u0647\\u0631\\u0628\\u0627\\u0621\",\"\\u0645\\u064a\\u0627\\u0647\",\"\\u0635\\u0631\\u0641 \\u0635\\u062d\\u064a\"]', 'سكني', 'https://eservicesredp.rega.gov.sa/public/OfficesBroker/ElanDetails/08de1c68-a6dc-42ea-844d-a1cd38d72015', NULL, NULL, 1, '7041434759'),
