(587, 'مفوض', 1, 'ارض', 'بيع', 'للبيع وخصوصا للمسثمرين', '💎ارض للبيع العاجل تعتبر فرصة استثمارية لانها قريبة من مدينة الملك عبدالله الاقتصادية والطريق الدولي ومطار الملك عبدالله الدولي الجديد والمراكز  الترفيهية والمشاريع اللي ماكتملت ومستشفى بيش العام  وشاطيء الهيئه الملكية ولأنها معروضه للبيع العاجل خفضنا المتر ١١٠ ريال\nومساحتها  ١٠٢٢١٦ متر مربع  وبصك زراعي الكتروني وسعر المتر بموقعها اقل من السوق بكثير\nمنطقة جازان محافظة بيش تقع ع شارع ٣٠ وطول الضلع ٢٣٠م\nمستقبلا استخداماتها سكني – صناعي – زراعي – أو مشاريع تطويرية كبرى... منطقة استراتيجية وقابلة للتطوير...\nتقع شمال غرب مدينة بيش والتمدد السكاني لبيش متجه شمال يعني جهتها ..\nملاااااااحظة .......\nترى مكانها ليس زراعية المكان تجاري من الدرجه الاولى ..فيه واحد مسوي كمباوند  حوالي ١٤٠ غرفة  وهي زراعيه وماهي بعيده عنها ..الان من كثر الشركات المستأجرة مؤجره بمليوني خمس مية بالسنه..كيف عاد لمن تتغير مستقبلا الى سكنية تجارية ..موقع استراتيجي...\nبوسما مع المالك...\nمسوق ووسيط عقاري معتمد من الهيئه العامة للعقار  رقم 100026493\n وثيقة معتمدة FL-624413488', 'منطقة جازان   مدينة  بيش  حي  الحزم 2 20', '[{\"name\":\"حمام\", \"number\":\"0\"},{\"name\":\"غرف نوم\", \"number\":\"0\"},{\"name\":\"صالات\", \"number\":\"0\"},{\"name\":\"مطبخ\", \"number\":\"0\"}]', '102216.14', '110', '[]', 5005, 'active', 'الحزم 2', '[]', '[]', NULL, '[\"1764854459_1000305853.jpg\",\"1764854459_1000305851.jpg\",\"1764854459_1000305849.jpg\",\"1764854459_1000305845.jpg\"]', NULL, '17.434479827887948', '42.52653855594061', 'بيش', '[]', 10, 450, 1, NULL, '[]', NULL, 'منطقة جا', NULL, 234324, '7100230650', NULL, '2025-12-04 10:16:43', '2026-05-01 02:52:54', '[]', NULL, '20', NULL, 'ارض', '473301001203', NULL, NULL, NULL, '1', '1100026493', '7100230650', '03/11/2025', '05/10/2026', '473301001203', '7100230650', '1100026493', 'صك إلكتروني', '7100230650', 'يحده شارع عرض ثمانية امتار و يليه مبارك عارضي و اخوانه يبدا من الشرق الى الغرب بزاوية 92 درجة و طول الضلع مائتين و ثمانية عشر مترا', 'يحده عقيلي عبدالله السعن يبدا من الشمال الى الجنوب بزاوية 92 درجة و طول الضلع اربعمائة و ثلاثين مترا و تسعة عشر سنتمترا', 'يحده عقيلي غازي مطاري و اخوانه يبدا من الجنوب الى الشمال بزاوية 88 درجة و طول الضلع خمسمائة و واحد متر و خمسين سنتمترا', 'يحده شارع بعرض ثلاثين مترا يبدا من الشرق الى الغرب براوية 106 درجة و طول الضلع مائتين و ثلاثين مترا', NULL, 'جنوبية', '11243775.4', 12345, '11', 'لاتوجد', '', 'قطعة الارض الزراعية الواقعة فى ام التنعيم بمحافظة بيش .', NULL, NULL, 'بدون', '[\"\\u0643\\u0647\\u0631\\u0628\\u0627\\u0621\",\"\\u0645\\u064a\\u0627\\u0647\"]', 'غير معرف', 'https://eservicesredp.rega.gov.sa/public/IndividualBroker/ElanDetails/08de1a6b-ecce-4762-8936-97e0f5cf62ed', NULL, NULL, 1, '1058920842'),
