(644, 'مفوض', 1, 'ارض', 'بيع', 'أرض بحي الحمر الشمالي ببريدة بالقصيم', 'للبيع ارض بحي الحمر بمدينة ببريدة بمنطقة القصيم\n\nسعر المتر 600ريال للمتر شامل الضريبة والسعي فقط على المشتري رسوم النقل\n\nالمساحة 375م\n\nالحد الشمالي أرض بطول 15م\nالحد الشرقي أرض بطول 25م\nالحد الغربي أرض بطول 25 م\nالحد الجنوبي شارع بطول 12م\n\nسعر الارض بحد 225000 ريال شامل الضريبة والسعي\n\nمعالم قريبة\nحديقة الحمر 350 م\nالدائري الغربي 550 م\nكبري الحمر 1 كلم\nمدارس قيم 600 م\nجامعة المستقبل 1 كلم\nطريق الملك سلمان (سابقا) 900 م طريق الملك فهد (سابقا) 2.5 كلم', 'منطقة القصيم   مدينة  بريدة  حي  الحمر الشمالي', '[{\"name\":\"حمام\", \"number\":\"0\"},{\"name\":\"غرف نوم\", \"number\":\"0\"},{\"name\":\"صالات\", \"number\":\"0\"},{\"name\":\"مطبخ\", \"number\":\"0\"}]', '375', '600', '[]', 2001, 'active', 'الحمر الشمالي', '[]', '[]', NULL, '[\"1768057420_128.jpg\",\"1768057420_130.jpg\",\"1768057420_131.jpg\"]', NULL, '26.343354060070734', '43.894026750294515', 'بريدة', '[]', 4, 501, 1, NULL, '[]', NULL, 'منطقة ال', NULL, 234324, '7200829875', NULL, '2026-01-10 12:03:15', '2026-04-26 12:24:40', '[]', NULL, '12', NULL, 'ارض', '1167318891500000', NULL, NULL, NULL, '2', '1200033971', '7200829875', '08/01/2026', '31/03/2026', '1167318891500000', '7200829875', '1200033971', ' صك السجل العقاري', '7200829875', NULL, NULL, NULL, NULL, NULL, 'جنوبية', '225000', 52371, 'ق/ب/6098', 'لايوجد ', '', NULL, NULL, NULL, '2', '[\"\\u0643\\u0647\\u0631\\u0628\\u0627\\u0621\",\"\\u0645\\u064a\\u0627\\u0647\"]', 'سكني', 'https://eservicesredp.rega.gov.sa/public/OfficesBroker/ElanDetails/08de4ed9-640f-46cc-8bc9-0023243d5523', 'مؤسسة كحيلة الاصيلة العقارية', '0505316353', 1, '7004239468');
