(653, 'مفوض', 32, 'شقة', 'بيع', 'شقة سكنية للبيع ، حي النور  بالدمام', '🔻   للبيع شقة تمليك بالمنطقة الشرقيه \n🕹️الموقع الدمام \n📍حي النور \n🔶المساحة 118\n🔶شارع 20 م\n🔶مكونه من 3 غرف\n🔶صاله كبيره وواسعه\n🔶مطبخ ، 3 دوراة مياه \n🔷الخدمات مصعد، عداد خاص\n🔷قريبه جدا للخدمات  \n🔷الشقه موجرة بعقد سنوي\n🔷موقف خاص ، \n🔶عمر الشقة 6 سنوات \n💵المطلوب 300 الف \n📞للتواصل 0591711040', 'المنطقة الشرقية   مدينة  الدمام  حي  النور 7', '[{\"name\":\"حمام\", \"number\":\"3\"},{\"name\":\"غرف نوم\", \"number\":\"3\"},{\"name\":\"صالات\", \"number\":\"1\"},{\"name\":\"مطبخ\", \"number\":\"1\"}]', '118.46', '290000', '[]', 1700, 'active', 'النور', '[]', '[]', NULL, '[\"1768393573_image_picker_86FB3DCB-0A3C-48BF-BDBF-A5E61DA267FF-3502-0000022107CA7734.jpg\",\"1768393573_image_picker_CD0BE490-0E22-4FF4-AB8B-AF19CF815D36-3502-0000022107EEDD02.jpg\",\"1768393573_image_picker_C08BBD13-76CD-461E-BE80-89034E47DAB5-3502-0000022107A09495.jpg\",\"1768393573_image_picker_660BE6C6-448C-44A2-B5B4-4F5B48C6616D-3502-0000022107DA7CBD.jpg\",\"1768393573_image_picker_77A92346-A872-4600-BD9F-136BDE54777F-3502-0000022107B1BD5E.jpg\",\"1768393573_image_picker_FE9C7648-3B29-4EA0-9738-EA2A4D358F48-3502-0000022107C52C8C.jpg\"]', NULL, '26.429604677167358', '50.035081492174015', 'الدمام', '[]', 5, 339, 1, 'ست سنوات', '[]', NULL, 'المنطقة ', NULL, 234324, '7100251757', NULL, '2026-01-14 09:25:46', '2026-05-01 02:51:19', '[]', NULL, '0', NULL, 'شقة', '460002817709', NULL, NULL, NULL, '1', '1100122252', '7100251757', '14/01/2026', '14/01/2027', '460002817709', '7100251757', '1100122252', 'صك إلكتروني', '7100251757', 'الوحدة رقم 51 /6 ومنور 1 الدرج والمصعد 4.90 + 0.70 + 1.50 + 0.70 + 3.00 + 1.10 + 1.50 + 1.55 + 1.70 + 2.00 + 1.80', NULL, NULL, NULL, NULL, 'جنوبية', NULL, 32444, '1300 / ش د', 'الشقة مرهونه للبنك 230 الف', '', 'حي  النور  بمدينة الدمام .', '3', NULL, '51', '[\"\\u0643\\u0647\\u0631\\u0628\\u0627\\u0621\",\"\\u0645\\u064a\\u0627\\u0647\",\"\\u0635\\u0631\\u0641 \\u0635\\u062d\\u064a\"]', 'سكني', 'https