(654, 'مفوض', 1, 'ارض', 'بيع', 'للبيع ارض بمخطط الليوان ببريدة بمنطقة القصيم', 'للبيع أرض في مخطط الليوان ببريدة بمنطقة القصيم\n\nالأطوال والتفاصيل :\n\nشمال شارع عرض 12 م + ﺧﺪﻣﺔ ﻭﻣﻮﺍﻗﻒ ﺳﻴﺎﺭﺍﺕ 15ﻣﺘﺮ ﻳﻠﻴﻪ ﻃﺮﻳﻖ ﻫﻴﻜﻠﻲ ﺃﺑﺮﺍﺝ ﻛﻬﺮﺑﺎﺀ ﻋﺮﺽ 40ﻣﺘﺮ\nجنوبا القطعة رقم 13/ 913 بطول 12 م\nشرقا القطعة رقم 10 / 913 بطول 35.08 م\nغربا القطعة رقم 913/14 بطول 35.01 م\n\nالبيع 160000 الف ريال\n\nغير شامل الضريبة والسعي', 'منطقة القصيم   مدينة  بريدة  حي  الليوان المفرق وكمب الطرق 1812', '[{\"name\":\"حمام\", \"number\":\"0\"},{\"name\":\"غرف نوم\", \"number\":\"0\"},{\"name\":\"صالات\", \"number\":\"0\"},{\"name\":\"مطبخ\", \"number\":\"0\"}]', '420.84', '381', '[]', 929, 'active', 'الليوان', '[]', '[]', NULL, '[\"1768395990_931.jpg\",\"1768395990_932.jpg\"]', NULL, '26.367477153075452', '43.78005525446576', 'بريدة', '[]', 4, 501, 1, NULL, '[]', NULL, 'منطقة ال', NULL, 234324, '7200837127', NULL, '2026-01-14 10:06:11', '2026-04-26 12:23:08', '[]', NULL, '12', NULL, 'ارض', '460001545027', NULL, NULL, NULL, '2', '1200033971', '7200837127', '14/01/2026', '30/05/2026', '460001545027', '7200837127', '1200033971', 'صك إلكتروني', '7200837127', 'شارع خدمة ومواقف سيارات 15متر يليه طريق هيكلي أبراج كهرباء عرض 40متر اثنى عشر متر', 'الجزء رقم 913/10 خمسة و ثلاثون متر و ثمانية سنتمتر', 'الجزء رقم 913/14 خمسة و ثلاثون متر و عشرة سنتمتر', 'الجزء رقم 913/13 اثنى عشر متر', NULL, 'شمالية', '160340.04', 52572, 'ق / ب / 6361', 'لايوجد', '', 'حي  المليداء  بمدينة بريدة .', NULL, NULL, '913 / 12', '[\"\\u0643\\u0647\\u0631\\u0628\\u0627\\u0621\"]', 'سكني', 'https://eservicesredp.rega.gov.sa/public/OfficesBroker/ElanDetails/08de536a-cd6d-49fc-8ae3-b94bdc26f923', 'مؤسسة كحيلة الاصيلة العقارية', '0505316353', 1, '7033168274'),
(655, 'مفوض', 5, 'فيلا', 'بيع', 'فيلا للبيع بمدينة جدة حي الكوثر', 'فرصة لا تُعوّض لامتلاك ڤيلا بنظام شقق في حي الحمدانية – جدة\n\nفيلا للبيع مستخدمة بموقع استراتيجي قريب من قاعة لندن، تجمع بين السكن العائلي الراقي والعائد الاستثماري المضمون بنظام الشقق.\nعمرالعقار فوق عشر سنوات\nالمساحة: 300 م\nعلى شارع عرض 20 م\nنظام شقق مستقلّة – مثالية للسكن أو الاستثمار\nتفاصيل التقسيم:\n\n🔹 الدور الأرضي\n4 غرف\nحمّامين\nصالة واسعة\nمطبخ\n🔹 الدور الأول\n5 غرف\n3 حمّامات\nصالة كبيرة\nمطبخ\n🔹 الدور الثاني\nغرفتان\nحمّامين\nمطبخ\nمخزن\nسطوح خاص\n⭐ مميزات الفيلا:\n✔ موقع مميّز بجوار جميع الخدمات\n✔ قريبة من القاعات والمرافق الحيوية\n✔ مدخل مستقل لكل شقة\n✔ موقف سيارة داخل الفيلا\n✔ خيار مثالي للعائلة الكبيرة أو للاستثمار بعائد ممتاز\n\n📞 لا تفوّت هذه الفرصة\nفيلا تجمع بين الموقع، المساحة، والتقسيم الذكي… جاهزة لتكون منزلك أو استثمارك الناجح.\nللاستفسار جوال / 0537488663\nالترخيص الإعلاني : 7100251065', 'منطقة مكة المكرمة   مدينة  جدة  حي  الكوثر ابن محيصن', '[{\"name\":\"حمام\", \"number\":\"7\"},{\"name\":\"غرف نوم\", \"number\":\"8\"},{\"name\":\"صالات\", \"number\":\"3\"},{\"name\":\"مطبخ\", \"number\":\"3\"}]', '300', '1500000', '[]', 1258, 'active', 'الكوثر', '[]', '[]', NULL, '[\"1768411289_image_picker_AD2FC802-40AF-4F99-B1D4-1073F0C1C92E-4049-00000103C07E94B1.png\",\"1768411289_image_picker_F4A37C9B-4A28-4B43-A513-531D7CA6BB0F-4049-00000103C0107A4C.png\",\"1768411289_image_picker_6340CDED-6311-4487-A9CC-B2E64F111F88-4049-00000103C024B89A.png\",\"1768411289_image_picker_D82ED12C-5DCC-469C-AA1B-341DF8A54D0E-4049-00000103C0A6A490.png\",\"1768411289_image_picker_97302730-AEDA-4241-B378-4258D09F35DE-4049-00000103C04E1741.png\"]', NULL, '21.729122210409567', '39.20010651070079', 'جدة', '[]', 2, 227, 1, 'اكثر من عشر سنوات', '[]', NULL, 'منطقة مك', NULL, 234324, '7100251065', NULL, '2026-01-14 14:21:19', '2026-05-01 02:51:20', '[]', NULL, '20', NULL, 'فيلا', '320215015062', NULL, NULL, NULL, '1', '1100098980', '7100251065', '12/01/2026', '25/07/2026', '320215015062', '7100251065', 