(656, 'مفوض', 1, 'ارض', 'بيع', 'ارض سكنيه بالمنار', 'للبيع أرض سكنية حي المنار الدمام\n المساحة 959،95 م جنوبية شارع 18متر يوجد بها عداد كهرباء و عداد ماء غرب مجمع النخيل قريبه جدا من طريق المطار قريبه من طريق ابو حدرية\nاخر سوم مليون و800 \nالعرض للمشتري المباشر لديكم فقط🏕️🏕️\nواتس 0582103597', 'المنطقة الشرقية   مدينة  الدمام  حي  المنار هلال الربعي', '[{\"name\":\"حمام\", \"number\":\"0\"},{\"name\":\"غرف نوم\", \"number\":\"0\"},{\"name\":\"صالات\", \"number\":\"0\"},{\"name\":\"مطبخ\", \"number\":\"0\"}]', '959.95', '1876', '[]', 1438, 'active', 'المنار', '[]', '[]', NULL, '[\"1768419544_image_picker_9668457F-0B38-46B8-A9D6-2378197BE196-17817-00000BC4F086C6B3.png\",\"1768419544_image_picker_C7AE0E6C-1D93-4967-924F-17656B6218C0-17817-00000BC4F0B61E7B.png\"]', NULL, '26.38399232161882', '50.02557733970651', 'الدمام', '[]', 5, 219, 1, NULL, '[]', NULL, 'المنطقة ', NULL, 234324, '7200736446', NULL, '2026-01-14 16:38:05', '2026-04-26 12:22:29', '[]', NULL, '18', NULL, 'ارض', '330113012114', NULL, NULL, NULL, '2', '1200019664', '7200736446', '25/10/2025', '01/08/2026', '330113012114', '7200736446', '1200019664', 'صك إلكتروني', '7200736446', 'قطعة رقم 68 ثلاثون متر و واحد سنتمتر', 'قطعة رقم 67 ثمانية و ثلاثون متر و أربعة سنتمتر', 'قطعة رقم 71 اثنين و ثلاثون متر و تسعون سنتمتر', 'شارع عرض 18 متر أربعة و عشرون متر و خمسون سنتمتر', NULL, 'جنوبية', '1800866.2', 32274, '671 / 1', 'الصك حر ', '', 'حي  المنار  بمدينة الدمام .', NULL, NULL, '69', '[\"\\u0643\\u0647\\u0631\\u0628\\u0627\\u0621\",\"\\u0645\\u064a\\u0627\\u0647\"]', 'سكني', 'https://eservicesredp.rega.gov.sa/public/OfficesBroker/ElanDetails/08de13b9-dffd-40e5-8819-055bac331840', 'مكتب الحضور العقاري', '0582103597', 1, '7026551932'),
(657, 'مفوض', 5, 'فيلا', 'بيع', 'فلتين للبيع في بقيق', 'للبيع فلتين جنب بعض في بقيق \nحي الربوه \nالفلل منفصله \nكل فيلا دورين\nكل دور مستقل بناء شخصي \nعداين كهرباء\nمواصفات كل فيلا \n462 م شارع 18 شمال \nالدور الارضي مجلس ومقلط وصاله و3 غرف نوم و4 دورات مياه\nالدور الثاني 5 غرف نوم ومطبخ و4 دورات مياه وصاله \nمطلوب مليون و127 الف شامل السعي  للفيلا الواحده تفاوض للصامل \nيوجد فديو للمهتم واتس \nترخيص 7200836438', 'المنطقة الشرقية   مدينة  بقيق  حي  حي الربوة - بقيق 18', '[{\"name\":\"حمام\", \"number\":\"8\"},{\"name\":\"غرف نوم\", \"number\":\"8\"},{\"name\":\"صالات\", \"number\":\"2\"},{\"name\":\"مطبخ\", \"number\":\"0\"}]', '461.948', '1100000', '[]', 1378, 'active', 'حي الربوة - بقيق', '[]', '[]', NULL, '[\"1768419785_image_picker_23CF787B-C12D-4BF5-AB96-E7DD539B15EC-17817-00000BC64B15D75D.jpg\",\"1768419785_image_picker_1718114D-2676-447F-A00B-51C1CD1BB23C-17817-00000BC64B43651F.jpg\",\"1768419785_image_picker_BDA95092-8607-42A4-ABEE-D0EEF31216E4-17817-00000BC64B4F1EC1.jpg\"]', NULL, '25.92249476027752', '49.60053211794018', 'بقيق', '[]', 5, 219, 1, 'سنة', '[]', NULL, 'المنطقة ', NULL, 234324, '7200836438', NULL, '2026-01-14 16:42:45', '2026-04-26 12:22:23', '[]', NULL, '18', NULL, 'فيلا', '160002663442', NULL, NULL, NULL, '2', '1200019664', '7200836438', '13/01/2026', '01/08/2026', '160002663442', '7200836438', '1200019664', 'صك إلكتروني', '7200836438', NULL, NULL, NULL, NULL, NULL, 'شمالية', NULL, 9599, 'ش.ب / 79 / س المعدل 3', 'لا يوجد ', '', 'الهوية العقارية رقم 20509900000548  الموصوفة بقطعة الأرض \"د64\"  الواقعة في مخطط ش.ب / 79 / س المعدل 2 في  مدينة بقيق', '8', NULL, 'بدون', '[\"\\u0643\\u0647\\u0631\\u0628\\u0627\\u0621\",\"\\u0645\\u064a\\u0627\\u0647\",\"\\u0635\\u0631\\u0641 \\u0635\\u062d\\u064a\"]', 'سكني', 'https://eservicesredp.rega.gov.sa/public/OfficesBroker/ElanDetails/08de52d6-7027-4323-8f48-68b6b435f09f', 'مكتب الحضور العقاري', '0582103597', 1, '7026551932'),
