(663, 'مفوض', 33, 'شقَّة صغيرة (استوديو)', 'إيجار', 'الدرعية غرفة موظفين للايجار', 'غرفة للإيجار في الدرعية – فرصة مميزة \n\nمجدّد بالكامل وجاهز للسكن، مع مطبخ مؤسّس بتجهيز عملي.\n\nالمميزات:\n	•	موقع هادئ ومطلوب في الدرعية\n	•	تشطيب مجدد ونظيف\n	•	مطبخ مؤسس\n	•	المياه والكهرباء على المالك\n\nمناسب للأفراد و الموظفين', 'منطقة الرياض   مدينة  الدرعية  حي  ظهرة العودة شرق الامام ابي حنيفة', '[{\"name\":\"حمام\", \"number\":\"1\"},{\"name\":\"غرف نوم\", \"number\":\"1\"},{\"name\":\"صالات\", \"number\":\"0\"},{\"name\":\"مطبخ\", \"number\":\"0\"}]', '460', '24000', '[]', 1768, 'active', 'ظهرة العودة شرق', '[]', '[]', NULL, '[\"1768475350_image_picker_91DA68B8-D5D7-4233-B667-430FB3634FCE-78881-00000B5811748AF4.jpg\"]', NULL, '24.75035287704599', '46.534205057027044', 'الدرعية', '[]', 1, 205, 1, 'اكثر من عشر سنوات', '[]', NULL, 'منطقة ال', NULL, 234324, '7100252078', NULL, '2026-01-15 08:08:53', '2026-05-01 02:51:11', '[]', NULL, '0', NULL, 'شقَّة صغيرة (استوديو)', '360692005372', 'video_1769013999.mov', NULL, NULL, '1', '1100252397', '7100252078', '15/01/2026', '15/11/2026', '360692005372', '7100252078', '1100252397', 'صك إلكتروني', '7100252078', NULL, NULL, NULL, NULL, NULL, 'شمالية', NULL, 13734, '43', 'لا يوجد', '', 'حي ظهرة العودة شرق في مدينة الدرعية', '1', NULL, '843', '[\"\\u0643\\u0647\\u0631\\u0628\\u0627\\u0621\",\"\\u0645\\u064a\\u0627\\u0647\",\"\\u0635\\u0631\\u0641 \\u0635\\u062d\\u064a\"]', 'سكني', 'https://eservicesredp.rega.gov.sa/public/IndividualBroker/ElanDetails/08de5420-1408-4aae-8a43-853bee9b7a56', 'أمل مسفر بن عايض القحطاني', '0575057070', 1, '1097244691'),
