(685, 'مفوض', 5, 'فيلا', 'إيجار', 'فيلا دبلكس للايجار حي العارض', 'للإيجار \nحي العارض \nفيلا دبلكس راقية بتصميم أنيق وتوزيع مثالي للمساحات، مناسبة للعائلات الباحثة عن الراحة والخصوصية.\n\nتفاصيل الفيلا:\n🔹 الدور الأرضي:\n	•	صالة واسعة بتصميم عصري\n	•	مطبخ راكب\n	•	مغاسل\n	•	دورة مياه\n\n🔹 الدور الثاني:\n	•	4 غرف نوم\n	•	غرفة ماستر\n	•	3 غرف نوم\n	•	دورة مياه\n\n🔹 الدور الثالث:\n	•	صالة متعددة الاستخدام\n	•	دورة مياه\n	•	جلسة خارجية كبيرة ومميزة\n	•	غرفة خادمة بدورة مياه\n	•	غرفة غسيل\n\n⭐ المميزات:\n	•	مكيفات راكبة\n	•	مطبخ راكب\n	•	تشطيب راقٍ\n	•	توزيع عملي للمساحات\n	•	جلسة خارجية مثالية للضيافة', 'منطقة الرياض   مدينة  الرياض  حي  العارض يوسف السيرافي', '[{\"name\":\"حمام\", \"number\":\"5\"},{\"name\":\"غرف نوم\", \"number\":\"4\"},{\"name\":\"صالات\", \"number\":\"2\"},{\"name\":\"مطبخ\", \"number\":\"1\"}]', '250.3', '120000', '[]', 1437, 'active', 'العارض', '[]', '[]', NULL, '[\"1768936597_image_picker_98624207-030B-4F7C-B83E-6407B8C6DD3A-40160-0000038D57BAA0A2.jpg\",\"1768936597_image_picker_C6C1DA2B-E6FB-4741-9304-037D2C07AAC9-40160-0000038D57D27FD4.jpg\",\"1768936597_image_picker_AB87A4BB-252A-46FB-AC2D-A37771192097-40160-0000038D57A8BEC3.jpg\",\"1768936597_image_picker_D20C0337-AED0-437D-A7CE-9AC7F967ACC3-40160-0000038D57C48C25.jpg\",\"1768936597_image_picker_0DDA2F92-DF07-4B93-A88B-AE42C0E576ED-40160-0000038D577AF656.jpg\",\"1768936597_image_picker_FD5FF243-9DC0-43E4-8677-583E6CB0BBC8-40160-0000038D579D9996.jpg\",\"1768936597_image_picker_5A906876-E1B2-431C-AF95-774CEEF20434-40160-0000038D576D6C0C.jpg\",\"1768936597_image_picker_EFC8CF4B-B319-4546-BC2D-2460F2F04165-40160-0000038D578F9224.jpg\"]', NULL, '24.90150261241148', '46.62163880460144', 'الرياض', '[]', 1, 205, 1, 'سنة', '[]', NULL, 'منطقة ال', NULL, 234324, '7100253499', NULL, '2026-01-20 16:16:17', '2026-05-01 02:51:05', '[]', NULL, '10', NULL, 'فيلا', '9555292851300003', NULL, NULL, NULL, '1', '1100252397', '7100253499', '20/01/2026', '17/11/2026', '9555292851300003', '7100253499', '1100252397'