(721, 'مفوض', 36, 'عمارة', 'بيع', 'فرصه استثمارية عماره للبيع', 'بسم الله الرحمن الرحيم\nفرررصه استثماريه بموقع مميز\nللبيع عمارة سكنيه مكونه من 17 شقه الشقق تتكون من 3 غرف و 4 غرف و 2 غرف بمنافعها\nالمساحة 1100 متر\nعلى ثلاثة واجهات شمالي، جنوبي، شرقي', 'منطقة جازان   مدينة  جازان  حي  المطار شارع شهيد الدين ثم الوطن  عادل علي علي نجمي', '[{\"name\":\"حمام\", \"number\":\"2\"},{\"name\":\"غرف نوم\", \"number\":\"4\"},{\"name\":\"صالات\", \"number\":\"1\"},{\"name\":\"مطبخ\", \"number\":\"1\"}]', '1084.5', '3000000', '[]', 961, 'active', 'المطار', '[]', '[]', NULL, '[\"1770617428_image_picker_5B8DCF27-D34A-43A4-AC1F-675F226C1761-29767-00000AE0DED7F50F.jpg\",\"1770617428_image_picker_2536FC2B-C133-4022-B11B-A225716D6453-29767-00000AE0DF3D24C1.jpg\",\"1770617429_image_picker_039C74C8-4077-4C3C-8D13-9DB566256B71-29767-00000AE0DF9E207E.jpg\",\"1770617429_image_picker_5BC14CDF-36AD-4DD2-9DCA-4418ECF0BE6F-29767-00000AE0E004F557.jpg\",\"1770617430_image_picker_9A435B8F-4A8C-4CDB-8911-CFF89856CC00-29767-00000AE0E011AE39.jpg\"]', NULL, '16.89284387493449', '42.57880769911504', 'جازان', '[{\"name\": \"توفر كهرباء\"}, {\"name\": \"توفر ماء\"}]', 10, 520, 1, 'سبع سنوات', '[]', NULL, 'منطقة جا', NULL, 234324, '7100259004', NULL, '2026-02-09 03:09:37', '2026-05-01 02:50:00', '[]', NULL, '10', NULL, 'عمارة', '772003012595', NULL, NULL, NULL, '1', '1100300849', '7100259004', '08/02/2026', '01/12/2026', '772003012595', '7100259004', '1100300849', 'صك إلكتروني', '7100259004', 'يحده سابقا ملك البائع وعلى عبدالله جابر خردلى وحالياً شارع عرض 10 م من نفس الأرض يبدأ من الغرب بطول 34.00 م ثم شطفة بطول 4.24 م', 'يحده شارع عرض 10 م يبدا من الشمال بطول 43.00 م', 'يحده ملك / عمر سالم حمادى يبدأ من الجنوب بطول 46.00 م', 'يحده سابقا محمد على طبيقى وحالياً شارع 10 م يبدأ من الشرق بطول 25.00 م', NULL, 'شمالية - جنوبية - شرقية', NULL, 82722, '77 أ س / ج', 'لايوجد', '', 'حي  المطار  بمدينة جيزان .', '58', NULL, '1', '[\"\\u0643\\u0647\\u0631\\u0628\\u0627\\u0621\",\"\\u0645\\u064a\\u0627\\u0647\"]',