(722, 'مفوض', 32, 'شقة', 'إيجار', 'شقة جديدة للايجار بالماجدية 150 حي عرقة', 'شقة جديدة للإيجار – الماجدية 150 | حي عرقة\n\nشقة سكنية جديدة بالكامل (ساكن أول) بموقع مميز، تشطيب حديث وجاهزة للسكن.\n\nالتفاصيل:\n	•	غرفتا نوم ماستر\n	•	صالة واسعة\n	•	3 دورات مياه\n	•	مطبخ راكب\n	•	مكيفات راكبة', 'منطقة الرياض   مدينة  الرياض  حي  عرقة الفوانيس', '[{\"name\":\"حمام\", \"number\":\"3\"},{\"name\":\"غرف نوم\", \"number\":\"2\"},{\"name\":\"صالات\", \"number\":\"1\"},{\"name\":\"مطبخ\", \"number\":\"1\"}]', '94.96', '76000', '[]', 944, 'active', 'عرقة', '[]', '[]', NULL, '[\"1770715131_image_picker_C28FB8EA-EDDF-458A-9F76-25B0C31BAD7A-67517-00000E6A5B0E8D7A.jpg\",\"1770715131_image_picker_78854BAA-9D7F-4ECF-A2FA-F2446AACEBE2-67517-00000E6A5B34212F.jpg\",\"1770715131_image_picker_E7264778-1024-4AC9-BB31-CAD83566CB2D-67517-00000E6A5AE9991A.jpg\",\"1770715131_image_picker_E06B6040-6B77-4846-A4D2-B72438918BC2-67517-00000E6A5AFE752A.jpg\",\"1770715131_image_picker_D73C4262-1276-49EC-8DD0-3B5B2E887EE7-67517-00000E6A5B229446.jpg\"]', NULL, '24.68022710798161', '46.5763460361153', 'الرياض', '[]', 1, 205, 1, 'جديد', '[]', NULL, 'منطقة ال', NULL, 234324, '7100259265', NULL, '2026-02-09 13:01:05', '2026-05-01 02:50:02', '[]', NULL, '0', NULL, 'شقة', '8923789874800089', 'video_1770653021.mov', NULL, NULL, '1', '1100252397', '7100259265', '09/02/2026', '08/11/2026', '8923789874800089', '7100259265', '1100252397', ' صك السجل العقاري', '7100259265', NULL, NULL, NULL, NULL, NULL, 'جنوبية', NULL, 12543, '3164', 'لا يوجد', '', NULL, '2', NULL, '1156/1 + 1154/1 + 1148/1 + 1150/1 + 1146/1 + 1152/1', '[\"\\u0643\\u0647\\u0631\\u0628\\u0627\\u0621\",\"\\u0645\\u064a\\u0627\\u0647\",\"\\u0635\\u0631\\u0641 \\u0635\\u062d\\u064a\"]', 'سكني', 'https://eservicesredp.rega.gov.sa/public/IndividualBroker/ElanDetails/08de67f3-9b4b-4095-8244-3a96cfb93eaf', 'أمل مسفر بن عايض القحطاني', '0575057070', 1, '1097244691'),
(723, 'مفوض', 36, 'عمارة', 'بيع', 'فرصة للمطورين عمارة هدد مساحة 690 م', '♦️فرصة للمطورين ♦️\nخلفية شارع الامير سلطان بن سلمان \n\n🔹عمارة للبيع 🔹\n• جدة - المروة\n• ⁠مساحة العقار 690 م \n• ⁠قريبة من شارع السبعين \n• ⁠هدد - فاضية حالياً \n• ⁠إفراغ فوري \n• ⁠الاطوال 23*30\n• ⁠قريبة من المطار \n• ⁠العرض مباشر من المالك \n\nسعر البيع /3,500,000 ريال \nقابل للتفاوض \n\nللتواصل يرجى الاتصال \nالوسيط العقاري \nضيف الله الزهراني \n0551228113 \n\n\n♦️ *البيع قريب وعاجل*♦️', 'منطقة مكة المكرمة   مدينة  جدة  حي  المروة ابن مهزيار', '[{\"name\":\"حمام\", \"number\":\"0\"},{\"name\":\"غرف نوم\", \"number\":\"0\"},{\"name\":\"صالات\", \"number\":\"0\"},{\"name\":\"مطبخ\", \"number\":\"0\"}]', '690', '3500000', '[]', 935, 'active', 'المروة', '[]', '[]', NULL, '[\"1770655026_image_picker_6A1512A5-C4F3-4A9D-8D0D-F1D8E9CD4470-16666-00000960B7D77400.jpg\",\"1770655026_image_picker_657B0EA3-F499-41BC-9696-37A39108169E-16666-00000960B7F496B2.jpg\",\"1770655026_image_picker_1BB71F2C-8292-416B-8673-6CDB44CF069C-16666-00000960B7E3E2FA.jpg\"]', NULL, '21.6243098373655', '39.18648752674349', 'جدة', '[{\"name\": \"توفر هاتف ارضي\"}, {\"name\": \"توفر كهرباء\"}, {\"name\": \"توفر ماء\"}]', 2, 499, 1, 'اكثر من عشر سنوات', '[]', NULL, 'منطقة مك', NULL, 234324, '7100258240', NULL, '2026-02-09 13:36:41', '2026-05-01 02:50:03', '[]', NULL, '10', NULL, 'عمارة', '393836016308', NULL, NULL, NULL, '1', '1100001947', '7100258240', '06/02/2026', '16/07/2026', '393836016308', '7100258240', '1100001947', 'صك إلكتروني', '7100258240', NULL, NULL, NULL, NULL, NULL, 'شمالية', NULL, 23542, '171 / ب', 'لايوجد', 'لا يوجد', 'حي المروة في  مدينة جدة', '10', NULL, '311', '[\"\\u0643\\u0647\\u0631\\u0628\\u0627\\u0621\",\"\\u0645\\u064a\\u0627\\u0647\",\"\\u0635\\u0631\\u0641 \\u0635\\u062d\\u064a\",\"\\u0647\\u0627\\u062a\\u0641\",\"\\u0623\\u0644\\u064a\\u0627\\u0641 \\u0636\\u0648\\u0626\\u064a\\u0629\",\"\\u062a\\u0635\\u0631\\u064a\\u0641 \\u0627\\u0644\\u0641\\u064a\\u0636\\u0627\\u0646\\u0627\\u062a \"]', 'سكن