(741, 'مفوض', 32, 'شقة', 'إيجار', 'شقة للايجار الخبر حي الخبر', 'للايجار شقة راقية في حي حي الحمراء - الخبر\nتفاصيل الشقة:\nمجلس واسع\n3 غرف نوم\n3 دورات مياه\nمطبخ أوروبي راكب\nمكيفات راكبة\nستائر فندقية أمريكية\nمصعد\nالموقع مميز وقريب من جميع الخدمات.', 'المنطقة الشرقية   مدينة  الخبر  حي  الحمراء العطايف', '[{\"name\":\"حمام\", \"number\":\"3\"},{\"name\":\"غرف نوم\", \"number\":\"3\"},{\"name\":\"صالات\", \"number\":\"1\"},{\"name\":\"مطبخ\", \"number\":\"1\"}]', '148', '50000', '[]', 763, 'active', 'الحمراء', '[]', '[]', NULL, '[\"1771460156_image_picker_FA1D75B9-8C2E-4540-BEBF-67C3A69870E5-8047-00000992CE6CA1F3.jpg\",\"1771460156_image_picker_67BC8631-2B8D-4E6A-94F5-23916941AE82-8047-00000992CE718116.jpg\",\"1771460156_image_picker_8711D9A6-90EA-48C5-ADC9-5350B80F84E5-8047-00000992CE984A79.jpg\",\"1771460156_image_picker_BD44132F-21F6-4362-A360-94DE08129C58-8047-00000992CEACCED1.jpg\",\"1771460156_image_picker_B2756995-AC08-4691-9664-843E7CF0AA51-8047-00000992CE9D696F.jpg\",\"1771460156_image_picker_5AB485CE-5AC3-4E1C-85DF-7AA607CCAB19-8047-00000992CE84A66F.jpg\",\"1771460156_image_picker_EB9FAAA1-28EB-4C5C-BB5F-AAC83035818A-8047-00000992CE7F9A12.jpg\",\"1771460156_image_picker_D48B114A-EF12-41A2-BCC6-3E9A280ACE0C-8047-00000992CE58744D.jpg\",\"1771460156_image_picker_DBBD6D21-D71F-4E78-9D88-3D455C21E336-8047-00000992CE61F870.jpg\",\"1771460156_image_picker_78BA6E38-0508-443F-8304-0463655C5518-8047-00000992CE920BE3.jpg\",\"1771460156_image_picker_87ABB01D-718C-4ACA-A095-1B58053048D6-8047-00000992CE66D419.jpg\",\"1771460156_image_picker_17B5D6BA-5C7B-4F2C-9913-DF6E37612DE0-8047-00000992CEA787A6.jpg\"]', NULL, '26.2318159314254', '50.202870934719044', 'الخبر', '[]', 5, 205, 1, 'سنتين', '[]', NULL, 'المنطقة ', NULL, 234324, '7100261938', NULL, '2026-02-18 21:15:37', '2026-05-01 02:49:20', '[]', NULL, '0', NULL, 'شقة', '998552032293', NULL, NULL, NULL, '1', '1100252397', '7100261938', '19/02/2026', '05/11/2026', '998552032293', '7100261938', '1100252397', 'وثيقة م