(791, 'مفوض', 1, 'ارض', 'بيع', '🎖️أرض مميزة للبيع – حي شوران(بالقرب من الجوازات – خلف محطة الرضا)🎖️', 'ارض في موقع مرتفع واستراتيجي، قريبة جداً من شارعين رئيسيين، وبالقرب من الارض مسجد ، مناسبة لمشروع سكني.\n\n📍 الموقع:\nشوران – بالقرب من الجوازات – خلف محطة الرضا\n\nالمساحة: 800 متر مربع\nواجهة جنوبية على مواقف سيارات\n\n\nالمواصفات:\nبالقرب من الارض مسجد\nأرض مرتفعة\nعليها رخصة إنشاء عمارة\nالأساسات جاهزة للبناء\nيتبقى: الردم + الصبة الأرضية\nعلى شارع عرض 16م تقريباً\nقريبة جداً من شارعين رئيسيين\nمن المالك مباشرة\n\nالمشروع المعتمد:\nتصميم دورين + ملحقين علوي\nكل دور يحتوي على 4 شقق\nكل شقة: 3 غرف + صالة + مطبخ + 2 حمام + بابين\nامكانية تعديل المخطط إلى 3 أدوار\n\n📏 الحدود والأطوال حسب الصك:\nشمالاً: 20م\nجنوباً: 20م\nشرقاً: 40م\nغرباً: 40م', 'منطقة المدينة المنورة   مدينة  المدينة المنورة  حي  الروابي عبدالله ابن عبدالرحمن ابن عمر', '[{\"name\":\"حمام\", \"number\":\"0\"},{\"name\":\"غرف نوم\", \"number\":\"0\"},{\"name\":\"صالات\", \"number\":\"0\"},{\"name\":\"مطبخ\", \"number\":\"0\"}]', '800', '2125', '[]', 13, 'active', 'الروابي', '[]', '[]', NULL, '[\"1775338507_image_picker_D9CCB521-A49C-4C1E-AAAA-8F40CF118F29-8637-000002AFE731B393.jpg\",\"1775338716_image_picker_E079C704-966C-4C2E-A976-CAEDCA011258-8637-000002B113E9E0E5.jpg\",\"1775338716_image_picker_BA425001-3ED0-4666-A43A-B2C15221710D-8637-000002B113F7C5C7.jpg\"]', NULL, '24.41273189749958', '39.66293635336758', 'المدينة المنورة', '[]', 3, 548, 1, NULL, '[]', NULL, 'منطقة ال', NULL, 234324, '7200842297', NULL, '2026-04-04 18:34:55', '2026-04-26 12:07:28', '[]', NULL, '16', NULL, 'ارض', '440114000679', NULL, NULL, 'video_1775338733.mov', '2', '1200042362', '7200842297', '18/01/2026', '28/10/2026', '440114000679', '7200842297', '1200042362', 'صك إلكتروني', '7200842297', 'القطعة رقم 46 عشرون متر', 'البعض القطعة رقم 48 والبعض القطعة رقم 47 أربعون متر', 'القطعة رقم 50 أربعون متر', 'مواقف سيارات South عشرون متر', NULL, 'جنوبية', '1700000', 42381, '634 / ت / 1413', 'بلا', '', 'حي  شوران / ق بمدينة المدينة المنورة .', NULL, NULL, '49 / ق', '[\"\\u0643\\u0647\\u0631\\u0628\\u0627\\u0621\",\"\\u0645\\u064a\\u0627\\u0647\",\"\\u0635\\u0631\\u0641 \\u0635\\u062d\\u064a\",\"\\u0647\\u0627\\u062a\\u0641\",\"\\u0623\\u0644\\u064a\\u0627\\u0641 \\u0636\\u0648\\u0626\\u064a\\u0629\",\"\\u062a\\u0635\\u0631\\u064a\\u0641 \\u0627\\u0644\\u0641\\u064a\\u0636\\u0627\\u0646\\u0627\\u062a \"]', 'غير متوفر', 'https://eservicesredp.rega.gov.sa/public/OfficesBroker/ElanDetails/08de56b8-a3d5-4b86-89f5-709153698db1', 'مكتب سدين للعقار', '0530084666', 1, '7003908675');
