(853, 'مفوض', 1, 'ارض', 'بيع', 'ارض في الصفا منطقة عمائر', 'ارض في الصفا منطقة عمائر \n\nمساحتها 625 متر \n\nشارع 15 متر\n\nأضلاعها علي الشارع 25 في 25 م\n\nمطلوب 3300000 ثلاثه مليون ،ثلاثمائة ألف \n\n🏢 يوجد شقق تحت الإنشاء \nلاستقبال عروضكم أو طلباتكم التواصل 0500944916', 'منطقة مكة المكرمة   مدينة  جدة  حي  الصفاء الخياط', '[{\"name\":\"حمام\", \"number\":\"0\"},{\"name\":\"غرف نوم\", \"number\":\"0\"},{\"name\":\"صالات\", \"number\":\"0\"},{\"name\":\"مطبخ\", \"number\":\"0\"}]', '625', '5280', '[]', 12, 'active', 'الصفاء', '[]', '[]', NULL, '[\"1781624238_image_picker_C3A05858-BF96-40B4-B25C-B565F3B3215B-1920-0000030DEA4F026A.jpg\"]', NULL, '21.583840753094904', '39.218613514916214', 'جدة', '[]', 2, 426, 1, NULL, '[]', NULL, 'منطقة مك', NULL, 234324, '7100291944', NULL, '2026-06-16 12:37:10', '2026-06-16 12:37:18', '[]', NULL, '15', NULL, 'ارض', '520204018818', NULL, NULL, NULL, '1', '1100003088', '7100291944', '16/06/2026', '16/12/2026', '520204018818', '7100291944', '1100003088', 'صك إلكتروني', '7100291944', 'قطعة رقم 381 خمسة و عشرون متر', 'قطعة رقم 382 خمسة و عشرون متر', 'شارع عرض 15 م خمسة و عشرون متر', 'قطعة رقم 385 خمسة و عشرون متر', NULL, 'غربية', '3300000', 23454, 'المنح / 11', 'لايوجد', '', 'حي  الصفا  بمدينة جدة .', NULL, NULL, '383', '[\"\\u0643\\u0647\\u0631\\u0628\\u0627\\u0621\",\"\\u0645\\u064a\\u0627\\u0647\",\"\\u0635\\u0631\\u0641 \\u0635\\u062d\\u064a\",\"\\u0623\\u0644\\u064a\\u0627\\u0641 \\u0636\\u0648\\u0626\\u064a\\u0629\"]', 'سكني', 'https://eservicesredp.rega.gov.sa/public/IndividualBroker/ElanDetails/08decbb8-6f0c-437c-89fc-ef0a97033c60', 'زينه محمد صالح الشهري', '0500944916', 1, '1016843995'),
