(855, 'مفوض', 5, 'فيلا', 'بيع', 'فلل فلوة', 'من شرق الرياض تقدم تمام العقارية مشروع فلوة السكني في حي غصون بالرياض.\n\nمجموعة فلل صُممت وفق أعلى معايير الجودة، لضمان استدامة القيمة العقارية ورفاهية السكن. يتميز المشروع بتكامل الخدمات والموقع الاستراتيجي، مع توفر مساحات متنوعة تلبي الاحتياجات السكنية المختلفة.', 'منطقة الرياض   مدينة  الرياض  حي  الجنادرية 559 الجنادرية', '[{\"name\":\"حمام\", \"number\":\"5\"},{\"name\":\"غرف نوم\", \"number\":\"4\"},{\"name\":\"صالات\", \"number\":\"3\"},{\"name\":\"مطبخ\", \"number\":\"1\"}]', '300', '1650000', '[]', 16, 'active', 'الجنادرية', '[]', '[]', NULL, '[]', NULL, '24.850013361627482', '46.89832522109467', 'الرياض', '[{\"name\": \"توفر كهرباء\"}, {\"name\": \"توفر ماء\"}, {\"name\": \"مدخل سيارة\"}, {\"name\": \"ملحق\"}, {\"name\": \"درج صالة\"}, {\"name\": \"حوش\"}, {\"name\": \"عرفة خادمة\"}, {\"name\": \"غرفة سائق\"}, {\"name\": \"التحكم بالتكيف\"}, {\"name\": \"الدخول الذكي\"}, {\"name\": \"التحكم باإنارة\"}]', 1, 712, 1, 'جديد', '[]', NULL, 'منطقة ال', NULL, 234324, '7100283516', NULL, '2026-06-17 12:32:40', '2026-06-17 12:35:24', '[]', NULL, '15', NULL, 'فيلا', '3793063861100000', 'video_1781710521.mov', NULL, NULL, '1', '1100292187', '7100283516', '14/05/2026', '14/08/2026', '3793063861100000', '7100283516', '1100292187', ' صك السجل العقاري', '7100283516', NULL, NULL, NULL, NULL, NULL, 'جنوبية', NULL, 13621, '3680', 'لا يوجد', '', NULL, '4', NULL, '800/14/16/1', '[\"\\u0635\\u0631\\u0641 \\u0635\\u062d\\u064a\",\"\\u0645\\u064a\\u0627\\u0647\",\"\\u0643\\u0647\\u0631\\u0628\\u0627\\u0621\"]', 'سكني', 'https://eservicesredp.rega.gov.sa/public/IndividualBroker/ElanDetails/08deb1c5-966c-4e41-86e5-05250caaa29b', 'ابراهيم سعد محمد التويم', '536495877', 1, '1133238137'),
(856, 'مفوض', 1, 'ارض', 'بيع', 'ارضين تجاريه بصك واحد في حي المصيف', 'ارض تجاريه في المصيف بتبوك\nقطعتين بصك واحد\nمساحة إجمالية: 1750 م²\nالأبعاد: 50 × 35\nعلى شارعين:\n▪️ شارع 50 م غربي \n▪️ شارع 20 م شرقي \n\nموقع استراتيجي مناسب لـ:\n* محطة\n* معرض\n* مجمع تجاري\n* مشروع استثماري\n\n💰 المطلوب: 5.900000 \nالسعر قابل للتفاوض للجادين', 'منطقة تبوك   مدينة  تبوك  حي  المصيف شارع ابي ذر الغفاري', '[{\"name\":\"حمام\", \"number\":\"0\"},{\"name\":\"غرف نوم\", \"number\":\"0\"},{\"name\":\"صالات\", \"number\":\"0\"},{\"name\":\"مطبخ\", \"number\":\"0\"}]', '1750', '3372', '[\"1781798971_image_picker_368FC299-434D-405C-B908-3791684B6398-1548-000002B648345FE8.jpg\"]', 10, 'active', 'المصيف', '[]', '[]', NULL, '[\"1781798921_image_picker_540F1FCF-63C3-47C9-B826-2E9E20491D96-1548-000002B5FFD1AA2F.jpg\"]', NULL, '28.461342342249857', '36.52439150916985', 'تبوك', '[]', 7, 426, 1, NULL, '[]', NULL, 'منطقة تب', NULL, 234324, '7100292624', NULL, '2026-06-18 13:08:31', '2026-06-18 13:09:31', '[]', NULL, '50', NULL, 'ارض', '560026268531', 'video_1781798941.mov', NULL, NULL, '1', '1100003088', '7100292624', '18/06/2026', '27/09/2026', '560026268531', '7100292624', '1100003088', 'صك إلكتروني', '7100292624', NULL, NULL, NULL, NULL, NULL, 'غربية - شرقية', '5901000', 47324, '403 / 38 / ت', 'لايوجد', '', 'حي المصيف في  مدينة تبوك', NULL, NULL, '1323  /  2', '[\"\\u0643\\u0647\\u0631\\u0628\\u0627\\u0621\",\"\\u0645\\u064a\\u0627\\u0647\",\"\\u0623\\u0644\\u064a\\u0627\\u0641 \\u0636\\u0648\\u0626\\u064a\\u0629\"]', 'استعمال مختلط', 'https://eservicesredp.rega.gov.sa/public/IndividualBroker/ElanDetails/08decd50-e4a0-4b02-88f6-521c0a7d263b', 'زينه محمد صالح الشهري', '0500944916', 1, '1016843995'),
